"""English wake-mode report from authored synthetic regression receipts."""
import datetime,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent;STATIC=ROOT/'static'
def esc(x):return html.escape(str(x))
def main():
 files=sorted(STATIC.glob('wake-browser-*.json'));p=files[-1];j=json.loads(p.read_text());units=json.loads((ROOT/'logs/unit-checks.json').read_text())
 rows=''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in (r['case'],'PASS' if r['passed'] else 'FAIL',r.get('endpoints',r.get('captions',[])),r.get('replies',r.get('reply','')),str(r.get('ignored',[]))+(' · speaker label correct: '+str(r['speaker_label_correct']) if 'speaker_label_correct' in r else '')))+'</tr>' for r in j['cases'])
 links=''.join(f'<li><a href="{x.name}">{x.name}</a></li>' for x in files)
 sounds=sorted(STATIC.glob('wake-sound-*.json'));sound= json.loads(sounds[-1].read_text()) if sounds else None
 sound_rows=''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in (r['case'],'PASS' if r['passed'] else 'FAIL',r.get('captions',[]),r.get('reply','')))+'</tr>' for r in (sound or {}).get('cases',[]))
 links+=''.join(f'<li><a href="{x.name}">{x.name}</a></li>' for x in sounds)
 checks={'generated':datetime.datetime.now(datetime.timezone.utc).isoformat(),'browser_receipt':p.name,'browser_passed':j['passed'],'source_sha256':j['source_sha256'],'unit_tests':units['tests'],'unit_passed':units['passed'],'physical_microphone_used':False,
  'sound_receipt':sounds[-1].name if sounds else None,'sound_passed':sound.get('passed') if sound else False,'sound_source_sha256':sound.get('source_sha256') if sound else None}
 (STATIC/'wake-release-checks.json').write_text(json.dumps(checks,indent=2))
 report=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby wake mode</title><style>body{{font:16px/1.6 system-ui;max-width:1100px;margin:auto;padding:24px;color:#20304a;background:#f7fafc}}section{{background:white;padding:20px;border-radius:15px;margin:16px 0}}table{{border-collapse:collapse;min-width:850px}}td,th{{border-bottom:1px solid #ddd;padding:8px;text-align:left;vertical-align:top}}.scroll{{overflow:auto}}a{{color:#15628d}}</style><h1>Hey Robby mode</h1>
<p><a href="/desk-robot/">Open live demo</a> · <a href="https://github.com/LAION-AI/Humaneness-Voice/blob/main/robby/WAKE_MODE.md">Implementation and reproduction</a> · <a href="VOICE_ASSISTANT_TEST_PROTOCOL.md">Test protocol</a></p>
<section><h2>Default behavior</h2><p>Say “Hey Robby” and your request. Your voice can continue without another wake phrase for ten seconds; the window is renewed after Robby finishes an answer. A different or uncertain voice needs its own wake phrase. Recognition is approximate; it is not authentication.</p><p>Speech-pause default: 300 ms, adjustable. That is not total response latency and may split a sentence. Automatic sound reactions default off. Explicit sound questions still use the short RAM buffer and an after-question window; captions can be wrong.</p></section>
<section><h2>Executed checks</h2><p>{units['tests']} offline tests {'passed' if units['passed'] else 'FAILED'}. The latest HTTPS digital-audio browser run {'passed' if j['passed'] else 'did not pass'}. It uses authored synthetic voices, actual Parakeet, ECAPA and TTS with PCM playback; LLM: {esc(j.get('llm','configured default'))}. This is not a physical-room accuracy evaluation.</p><div class="scroll"><table><tr><th>Case</th><th>Result</th><th>Recognized / captioned</th><th>Spoken text</th><th>Ignored reason</th></tr>{rows}</table></div><p>Source fingerprint: <code>{esc(j['source_sha256'])}</code>.</p></section>
<section><h2>Explicit sound questions with automatic reactions off</h2><p>These tests use the same wake-enrolled synthetic voice, an authored music fixture and the real captioner. LLM: {esc((sound or {}).get('llm','not recorded'))}. Before and after windows are evaluated independently; results are uncertain and captions can mistake speech for sound.</p><div class="scroll"><table><tr><th>Sound position</th><th>Result</th><th>Sound captions</th><th>Spoken response</th></tr>{sound_rows}</table></div><p>{'Latest two-case sound test passed.' if sound and sound.get('passed') else 'Latest sound test was incomplete or failed; inspect the raw receipt.'} The configured Qwen provider returned HTTP 429 during repeated tests; the test can explicitly select the local model without changing the demo default.</p></section>
<section><h2>Limits and previous failures</h2><p>Earlier attempts are preserved below. A 300-ms pause split an introduction into two answers, and an earlier version let the ten-second window expire while Robby was still replying. The current version permits the same voice during playback and renews the window after playback ends. Earlier tests also exposed a sound buffer that was too short and a voice embedding distorted by preceding music; the bounded buffer and tail-window verification were revised. Compare source fingerprints rather than treating earlier failures as current results.</p><p>The second-speaker introduction may also contain an ignored short continuation even when its first wake turn succeeds. Open mode can admit the returning speaker under an unnamed label; a direct identity question now asks for the name instead of guessing a previous person's name. A case labelled PASS for mode switching does not prove every speaker label or every fragment was correct. These few clips do not establish performance with real users, simultaneous voices, a television, echoed playback, short Stop commands or similar voices. False accepts and missed matches remain possible; the mode is not a biometric security boundary. If recognition is uncertain, repeat the wake phrase or disable the mode.</p><details><summary>Raw test attempts</summary><ul>{links}</ul></details></section></html>'''
 (STATIC/'wake-report.html').write_text(report);print(json.dumps(checks))
if __name__=='__main__':main()
